# Write the models A of the reference-precision tests (exact doubles), with their trial
# eigenvalues, to tests/testthat/reference/; tests/reference/reference.py then adds the
# 256-bit reference norms. Run in the image from the repository root:
#   docker run --rm -v "$PWD":/repo -w /repo --entrypoint Rscript processor-seizure-fragility:dev tests/reference/make_cases.R
#   python3 tests/reference/reference.py tests/testthat/reference      (needs python-flint, numpy)
# The A matrices are stored, not regenerated by the tests: the ridge fit goes through BLAS, so
# its last bits depend on the machine, and the reference is for these exact matrices.
Sys.setenv(APP_ROOT = normalizePath("."))
source("R/main.R")
source("tests/testthat/helper-fixture.R")
out <- "tests/testthat/reference"
dir.create(out, showWarnings = FALSE)
nSearch <- 20L
write_case <- function(name, A) {
  con <- file(file.path(out, paste0(name, "_A.bin")), "wb")
  writeBin(c(nrow(A), nSearch), con, size = 4, endian = "little")
  writeBin(as.vector(A), con, size = 8, endian = "little")
  lam <- trial_lambdas(nSearch)
  writeBin(c(Re(lam), Im(lam)), con, size = 8, endian = "little")
  close(con)
  cat(sprintf("%s: %d channels, ||A||_2 = %.3g, spectral radius %.3g, lambda %g\n", name, nrow(A),
              norm(A, "2"), max(Mod(eigen(A, only.values = TRUE)$values)), attr(A, "lambda")))
}
fit <- function(x, win, start) {
  x <- ez_standardize(x)
  si <- start + seq_len(win - 1L)
  ez_ridge_search(x[, si, drop = FALSE], x[, si + 1L, drop = FALSE], NULL)
}
# More channels than samples per window (as >= 128 channels at 512 Hz in 250 ms), and an
# artefact elsewhere in the segment that sets EZFragility's power-of-ten scaling (as on the
# demo clips): the penalty dominates, A is tiny and the fast engine's Gram determinant cancels.
x <- synth_recording(n_ch = 140, fs = 256, dur = 4, onset = 2, seed = 7)
x[5, 900] <- 200 * max(abs(x))
A <- fit(x, 64L, 300L)
write_case("wide", A)
# The same model scaled to ||A||_2 = 0.6: the Neumann series near its limit (NEUMANN_Q 0.7).
write_case("wide06", structure(A * (0.6 / norm(A, "2")), lambda = attr(A, "lambda")))
# Fewer channels than samples: A has eigenvalues near the unit circle.
write_case("narrow", fit(synth_recording(n_ch = 16, fs = 256, dur = 4, onset = 2, seed = 8), 128L, 500L))
